-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "koKR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.hunter.ranged.Name"] = "원거리"
L["rm.era.hunter.ranged.Description"] = "1레벨부터 60레벨까지 모든 특성 트리의 모든 사냥꾼용입니다. 사냥꾼의 징표, 조준 사격, 자동 사격으로 끌어옵니다. 혼자일 때는 소환수가 방어를 맡습니다: 내 독사 쐐기, 그다음 마나가 절반을 넘는 동안에만 조준 사격, 신비한 사격, 일제 사격, 소환수가 생기기 전에는 카이팅용 충격포를 사용합니다. 그룹에서는 자동 사격이 절대 늦어지지 않도록 자동 사격 직후에 조준 사격과 일제 사격, 공격대 밖에서는 독사 쐐기, 신비한 사격은 조준 사격 전이나 죽어 가는 대상에게만 사용합니다. 적이 너무 가까우면 근접 기술, 이동 중에는 즉시 시전 기술, 적이 셋 이상이면 일제 사격과 연발 사격을 사용합니다. 알림: 매의 상(그 전에는 원숭이의 상), 정조준 오라, 소환수 관리, 정예와 인스턴스에서 속사, 야수의 격노, 종족 특성, 위협과 죽은척하기. 덫, 날개 절단, 먹이주기, 평정의 사격, 위치 선정은 직접 판단합니다."
L["rm.era.hunter.ranged.icyveins.Name"] = "원거리, 자동 사격 끊기 (Icy Veins)"
L["rm.era.hunter.ranged.icyveins.Description"] = "기본적으로 꺼져 있습니다. 공격 속도가 3.0초보다 빠른 원거리 무기라면 켜세요. 사냥꾼: 원거리와 같지만, 그룹에서는 자동 사격이 늦어지더라도 조준 사격과 일제 사격을 준비되는 즉시 사용하고, 독사 쐐기는 쓰지 않으며, 속사, 야수의 격노, 종족 특성은 전투마다 사용합니다."
L["rm.era.hunter.ranged.simulator.Name"] = "원거리, 공격대 독사 쐐기 (시뮬레이터)"
L["rm.era.hunter.ranged.simulator.Description"] = "기본적으로 꺼져 있습니다. 공격대에 내 쐐기를 걸 약화 효과 자리가 있다면 켜세요. 사냥꾼: 원거리와 같지만, 그룹에서는 공격대를 포함해 어디서나 독사 쐐기를 유지하며, 조준 사격과 일제 사격이 모두 재사용 대기 중일 때 5초 미만이면 갱신하고, 신비한 사격은 쓰지 않습니다."
L["rm.forever.hunter.ranged.Name"] = "원거리 (Wowhead)"
L["rm.forever.hunter.ranged.Description"] = "1레벨부터 60레벨까지 모든 원거리 사냥꾼(야수, 사격, 그리고 타조 발차기 전까지의 생존)용이며, Forever 사냥꾼의 기본값입니다. 끌어오기: 사냥꾼의 징표, 신속한 사냥이 지속되는 동안 저격, 자동 사격. 그다음 내 독사 쐐기, 공유 재사용 대기시간에 맞춰 매 소환 두 번과 신비한 사격 한 번(매 소환 전에는 재사용 대기시간마다 신비한 사격), 신속한 사냥 중이거나 정예에게 저격, 조준 사격. 둘 이상의 적과 싸우면: 조준 사격 대신 일제 사격, 근처에 셋이면 폭발의 덫, 다섯이면 연발 사격. 이동 중: 즉시 시전 사격만. 근접 거리의 몹에게는 랩터의 일격과 살쾡이의 이빨. 알림: 매의 상(그 전에는 원숭이의 상), 정조준 오라, 야수 부르기, 야수 되살리기, 속사, 정예 상대나 던전에서 야수의 격노와 피의 격노, 몹이 나를 공격하면 위협. 소환수 명령, 먹이 주기, 카이팅, 죽은척하기는 직접 판단합니다. 고독한 늑대로 플레이한다면 소환수 알림을 끄세요. 이 로테이션은 Forever가 애드온에 숨기는 마나나 누구의 생명력도 읽지 않으므로, 사냥꾼의 징표와 독사 쐐기는 모든 대상에게 걸고 동물 치료는 직접 판단합니다."
L["rm.forever.hunter.ranged.mobalytics.Name"] = "원거리, 마나 절약 (Mobalytics)"
L["rm.forever.hunter.ranged.mobalytics.Description"] = "Mobalytics의 마나 절약 레벨업 방식으로, 추천 Wowhead 원거리 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 내 독사 쐐기를 유지하고, 매 소환 하나를 유지하며, 조준 사격(적이 둘 이상이면 일제 사격), 매 소환을 배운 뒤에는 신비한 사격을 쓰지 않습니다. Forever에서는 대상의 생명력이 숨겨져 있으므로 생명력이 충분한 대상에게 쓰는 두 번째 매는 빠져 있습니다. 끌어오기, 근접, 이동, 알림은 Wowhead 기본 제공 로테이션과 같습니다."
L["rm.forever.hunter.survival.Name"] = "생존 근접 (Wowhead)"
L["rm.forever.hunter.survival.Description"] = "생존이 주 특성 트리이고 21포인트(타조 발차기 계층)를 투자한 뒤의 쌍수 근접 생존 로테이션입니다(그 전에는 공략의 조언대로 원거리 기본 제공 로테이션으로 레벨업합니다). 사냥꾼의 징표와 독사 쐐기로 끌어온 뒤 살쾡이의 이빨, 타조 발차기, 랩터의 일격, 역습을 사용하며, 적이 셋 이상이면 폭발의 덫을 사용합니다. 근접 거리 밖에서는 사격합니다: 독사 쐐기, 신비한 사격, 조준 사격, 자동 사격. 알림: 야수의 상, 사냥꾼의 징표(사냥감 노출에 필요), 정예 상대나 던전에서 속사와 피의 격노, 대상의 주의를 끌고 있는 동안 공격 저지, 소환수 관리(Forever에서는 생명력이 숨겨져 있으므로 동물 치료는 직접 판단합니다). 선택 단계인 제물의 덫은 기본적으로 꺼져 있습니다."
L["rm.forever.hunter.survival.weave.Name"] = "생존 양손 위빙 (Wowhead)"
L["rm.forever.hunter.survival.weave.Description"] = "양손 무기 생존 사냥꾼을 위한 Wowhead의 들어갔다 나오는 위빙으로, 추천 생존 근접 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 근접 거리에서: 살쾡이의 이빨과 랩터의 일격. 랩터의 일격까지 2.5초보다 많이 남았으면 타조 발차기 후 빠져나옵니다. 근접 거리 밖에서: 랩터의 일격이 거의 준비될 때까지 독사 쐐기, 신비한 사격, 조준 사격, 자동 사격을 사용한 뒤 다시 들어갑니다. 이동은 직접 하며, RM은 거리를 따라갑니다."
L["rm.mop.hunter.beastmastery.Name"] = "추천"
L["rm.mop.hunter.beastmastery.Description"] = "야수 전문화에서 자동으로 선택됩니다. 사냥꾼의 징표와 살상 명령으로 시작한 뒤: 마무리 사격, 살상 명령(야수의 격노가 곧 준비되면 잠시 보류), 저승까마귀, 스라소니 돌진, 특성을 찍었다면 광포한 야수와 6단계 특성 사격, 광기 5중첩(또는 곧 사라질 4중첩)에서 집중 사격(야수의 격노 중에는 제외), 오래 살아남을 대상에게 독사 쐐기, 이를 갱신하는 코브라 사격, 집중 80이거나 야수의 격노 중에 신비한 사격, 그다음 코브라 사격(81레벨 전에는 고정 사격). 적이 둘 이상 나와 싸우면 일제 사격으로 야수의 회전베기를 유지하고, 큰 무리에서는 남는 집중이 있을 때 살상 명령을 쓰며, 셋부터 폭발의 덫을 제안합니다. 알림: 소환수 부르기, 되살리기, 치료, 매의 상 또는 강철매의 상, 반격의 사격, 열정, 그리고 가치 있는 전투(정예, 던전이나 공격대, 또는 오래 살아남을 대상)에서 야수의 격노, 속사, 쇄도, 종족 특성. 덫 배치, 눈속임, 죽은척하기, 방어 기술은 직접 판단하며, 활기와 공격 저지 알림은 기본적으로 꺼져 있습니다."
L["rm.mop.hunter.marksmanship.Name"] = "추천"
L["rm.mop.hunter.marksmanship.Description"] = "사격 전문화에서 자동으로 선택됩니다. 조준 사격을 미리 시전한 뒤: 초점 고정을 유지하기 위해 고정 사격 두 번씩(63레벨부터), 키메라 사격, 오래 살아남을 대상에게 독사 쐐기, 발사!로 즉시 시전이 될 때마다 조준 사격, 마무리 사격, 특성 기술, 그리고 대상 생명력이 80%를 넘거나, 속사나 피의 욕망 중이거나, 집중 85이거나, 키메라 사격이 몇 초 남았을 때 일반 시전 조준 사격. 신비한 사격은 이동 중에만, 그 외에는 고정 사격. 적이 넷 이상이면: 키메라 사격, 즉시 시전 조준 사격, 일제 사격, 마무리 사격, 폭발의 덫. 알림은 다른 사냥꾼 기본 제공 로테이션과 같습니다. 남는 집중을 신비한 사격에 쓰는 것을 선호한다면 신비한 사격 변형을 사용하세요."
L["rm.mop.hunter.marksmanship.icyveins.Name"] = "신비한 사격 소모 (Icy Veins)"
L["rm.mop.hunter.marksmanship.icyveins.Description"] = "Icy Veins, Method, wowtbc.gg, Hekili가 플레이하는 방식으로, 사격 기본 제공 로테이션의 대안입니다: 일반 시전 조준 사격은 대상 생명력 80% 초과나 속사 또는 피의 욕망 중에만 사용하고, 남는 집중은 대신 60에서 신비한 사격에 씁니다. 초점 고정은 4초 미만일 때 갱신하며, 적이 넷 이상이면 일제 사격이 먼저입니다. 기본적으로 꺼져 있습니다: 이것을 켜고 사격 기본 제공 로테이션을 끄거나, 이것의 우선순위를 높이세요."
L["rm.mop.hunter.survival.Name"] = "추천"
L["rm.mop.hunter.survival.Description"] = "생존 전문화에서 자동으로 선택됩니다. 사냥꾼의 징표, 검은 화살, 폭발 사격으로 시작한 뒤: 재사용 대기시간마다와 실탄 장전마다 폭발 사격, 마무리 사격, 오래 살아남을 대상에게 검은 화살, 특성 기술, 코브라 사격으로 독사 쐐기 유지, 집중 75이거나 사냥의 전율이 있거나 검은 화살이 곧 준비되지 않으면 55에서 신비한 사격, 그다음 코브라 사격(81레벨 전에는 고정 사격). 적이 둘 이상이면: 집중이 가득하고 실탄 장전이 있으면 일제 사격 먼저, 대상 다섯까지 폭발 사격, 마무리 사격, 검은 화살, 셋부터 폭발의 덫, 소모용 일제 사격. 알림은 다른 사냥꾼 기본 제공 로테이션과 같으며, 실탄 장전 발동을 위한 덫은 직접 판단합니다."
L["rm.mop.hunter.unspecialized.Name"] = "전문화 선택 전"
L["rm.mop.hunter.unspecialized.Description"] = "1–9레벨과 아직 전문화를 고르지 않은 사냥꾼용이며, 전문화를 고르는 즉시 야수, 사격, 생존 기본 제공 로테이션이 넘겨받습니다. 사냥꾼의 징표와 신비한 사격으로 끌어온 뒤, 오래 살아남을 대상에게 독사 쐐기, 적이 셋 이상이면 일제 사격, 신비한 사격, 고정 사격, 자동 사격을 사용합니다. 소환수를 부르고, 되살리고, 치료하며, 매의 상을 유지하도록 알려 줍니다."
L["rm.retail.hunter.beastmastery.Name"] = "Blizzard 전투 보조"
L["rm.retail.hunter.beastmastery.Description"] = "야수 전문화에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며(소환수도 직접 부릅니다), 시전이나 정신 집중 중에는 기다립니다. 이와 함께 전투 보조가 플레이어에게 맡기는 것을 알려 줍니다: 전투 중 유혈과 종족 재사용 대기시간 기술, 차단 가능한 시전에 반격의 사격, 전투 중 준비될 때마다 적자생존. 적의 시전은 전투 중 숨겨지므로 차단은 게임이 시전을 보여 주는 곳에서만 강조되며, Retail에서는 생명력이 숨겨지므로 방어 기술(활기와 거북의 상 포함)을 언제 쓸지는 직접 판단합니다. 장신구, 눈속임, 소환수 관리는 직접 판단합니다."
L["rm.retail.hunter.beastmastery.guide.Name"] = "참고용 (SimulationCraft와 Icy Veins)"
L["rm.retail.hunter.beastmastery.guide.Description"] = "참고용이며 기본적으로 꺼져 있습니다. 최적화된 야수 우선순위입니다. 한밤 전투에서는 충전, 재사용 대기시간, 발동 효과가 애드온에 숨겨지므로 그곳에서는 실행할 수 없습니다. 읽어 보거나, 복제해서 실험해 보세요. Retail에서는 집중이 숨겨집니다. 전투 전에 소환수를 부르고 대상에게 사냥꾼의 징표를 겁니다. 야수의 격노 직전이나 충전이 가득 차기 전에 날카로운 사격; 야수의 격노; 무리의 지도자의 포효나 자연의 동맹 발동 시, 또는 야수의 격노까지 오래 남았으면 자유롭게 살상 명령; 코브라 송곳니 발동 시 코브라 사격; 코브라 사격; 코브라 사격에 쓸 집중이 부족하면 날카로운 사격. 어둠 순찰자: 부패의 사격 중 검은 화살, 끝날 때 울부짖는 화살. 적이 셋 이상(야수의 회전베기가 있으면 둘 이상): 야수의 회전베기를 시작하기 위해 마구잡이 난타, 그다음 지속되는 동안 살상 명령, 날카로운 사격, 코브라 사격. 알림: 유혈, 그리고 전투 보조 기본 제공 로테이션의 유틸리티 알림."
L["rm.retail.hunter.initial.Name"] = "Blizzard 전투 보조"
L["rm.retail.hunter.initial.Description"] = "전문화를 선택하기 전(게임이 사냥꾼의 초기 전문화를 보고하는 동안)에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며, 시전이나 정신 집중 중에는 기다립니다. 이와 함께 모든 사냥꾼 기본 제공 로테이션이 공유하는 알림을, 해당 주문을 배운 뒤에 각각 제공합니다. 10레벨에 전문화를 선택하면 해당 전문화의 기본 제공 로테이션이 대신합니다."
L["rm.retail.hunter.marksmanship.Name"] = "Blizzard 전투 보조"
L["rm.retail.hunter.marksmanship.Description"] = "사격 전문화에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며, 시전이나 정신 집중 중에는 기다립니다. 이와 함께 전투 보조가 플레이어에게 맡기는 것을 알려 줍니다: 전투 중 정조준과 종족 재사용 대기시간 기술, 차단 가능한 시전에 반격의 사격, 전투 중 준비될 때마다 적자생존. 적의 시전은 전투 중 숨겨지므로 차단은 게임이 시전을 보여 주는 곳에서만 강조되며, Retail에서는 생명력이 숨겨지므로 방어 기술(활기와 거북의 상 포함)을 언제 쓸지는 직접 판단합니다."
L["rm.retail.hunter.marksmanship.guide.Name"] = "참고용 (SimulationCraft와 Icy Veins)"
L["rm.retail.hunter.marksmanship.guide.Description"] = "참고용이며 기본적으로 꺼져 있습니다. 다음 조준 사격 전에 정밀 사격을 소모하는 최적화된 사격 우선순위입니다. 한밤 전투에서는 발동 효과와 충전이 숨겨지므로 그곳에서는 실행할 수 없습니다. Retail에서는 집중이 숨겨지므로 무리를 상대로 집중 70에서 쓰는 일제 사격은 빠집니다. 대상에게 사냥꾼의 징표를 걸고 조준 사격으로 시작합니다. 파수꾼: 폭발 사격, 연발 공격, 정조준, 효과 시간이 끝나기 전에 달빛 회전 표창, 정밀 사격 없이 정조준 중 조준 사격, 속사, 마무리 사격, 정밀 사격 발동 시 일제 사격(히드라의 상이 있으면 적 둘) 또는 신비한 사격, 조준 사격, 달빛 회전 표창, 고정 사격. 어둠 순찰자: 정밀 사격 발동 시 검은 화살을 먼저, 실탄 장전 중에는 폭발 사격 없음, 충전이 가득 차기 전에 조준 사격, 울부짖는 화살. 교묘한 사격이 있고 적이 셋 이상: 폭발 사격, 연발 공격, 교묘한 사격을 걸기 위해 일제 사격, 정조준, 그다음 지속되는 동안 속사와 조준 사격. 명중 30중첩이나 표식 없는 대상에 맞춘 정조준 사용은 직접 판단합니다."
L["rm.retail.hunter.survival.Name"] = "Blizzard 전투 보조"
L["rm.retail.hunter.survival.Description"] = "생존 전문화에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며(소환수도 직접 부릅니다), 시전이나 정신 집중 중에는 기다립니다. 이와 함께 전투 보조가 플레이어에게 맡기는 것을 알려 줍니다: 전투 중 제압과 종족 재사용 대기시간 기술, 차단 가능한 시전에 재갈, 전투 중 준비될 때마다 적자생존. 적의 시전은 전투 중 숨겨지므로 차단은 게임이 시전을 보여 주는 곳에서만 강조되며, Retail에서는 생명력이 숨겨지므로 방어 기술(활기와 거북의 상 포함)을 언제 쓸지는 직접 판단합니다."
L["rm.retail.hunter.survival.guide.Name"] = "참고용 (SimulationCraft)"
L["rm.retail.hunter.survival.guide.Description"] = "참고용이며 기본적으로 꺼져 있습니다. 살상 명령으로 창끝을 쌓고 제압, 붐스틱, 야생불 폭탄, 랩터의 일격으로 소모하는 SimulationCraft의 생존 우선순위입니다. 한밤 전투에서는 창끝과 충전이 숨겨지므로 그곳에서는 실행할 수 없습니다. 소환수를 부르고 대상에게 사냥꾼의 징표를 건 뒤 야생불 폭탄으로 시작합니다. 파수꾼: 창끝이 없으면 살상 명령, 붐스틱, 파수꾼의 표식 발동 시 야생불 폭탄, 제압이 준비되었으면 그 전에 살상 명령, 제압, 달빛 회전 표창, 랩터의 일격, 그다음 살상 명령, 야생불 폭탄, 제압. 무리의 지도자: 무리의 지도자의 포효 발동 시 살상 명령, 그다음 창끝이 있을 때 제압, 야생불 폭탄, 붐스틱, 랩터의 일격. 적이 셋 이상: 제압 전에 붐스틱과 야생불 폭탄, 랩터의 휩쓸기. 알림: 근접 거리 밖에서 독수리의 상, 그리고 유틸리티 알림."
L["rm.sod.hunter.melee.Name"] = "근접 (SoD)"
L["rm.sod.hunter.melee.Description"] = "디스커버리 시즌 서버에서 측방 강타, 비룡의 일격 또는 저미기를 새기고 키메라 사격과 폭발 사격은 새기지 않았을 때 선택됩니다. 측방 강타 강화 효과를 유지하고, 랩터의 격노 4중첩에서 살쾡이의 이빨, 절단 강타에 비룡의 일격, 초기화될 때마다 랩터의 일격, 그다음 살쾡이의 이빨, 비룡의 일격, 측방 강타, 저미기를 사용하며, 제물의 덫과 날개 절단은 빈 순간에만 사용합니다. 적이 셋 이상이면 저미기와 폭발의 덫, 대상에게 닿을 수 없는 동안에는 독사 쐐기와 사격 기술을 사용합니다. 알림: 송골매의 상(60레벨 전에는 매의 상), 마나 5% 미만에서 독사의 상, 소환수 관리(고독한 늑대를 새겼다면 없음), 측방 강타가 중첩되면 속사와 종족 특성, 야수의 격노. 위치 선정과 소환수 명령은 직접 판단합니다."
L["rm.sod.hunter.ranged.Name"] = "원거리 (SoD)"
L["rm.sod.hunter.ranged.Description"] = "디스커버리 시즌 서버의 1레벨부터 60레벨까지 모든 원거리 사냥꾼용이며, 룬은 새기면 사용합니다. 독사 쐐기는 항상 유지하고 키메라 사격으로 갱신합니다. 마무리 사격 다리 룬이 있으면: 교묘한 사격 4중첩에서 일제 사격, 속사 중과 마무리 구간의 대상에게 마무리 사격, 키메라 사격, 그다음 일제 사격이 재사용 대기 중일 때 폭발의 덫과 신비한 사격. 없으면: 키메라 사격, 저격 훈련 2중첩에서 조준 사격(그 룹이 없으면 자동 사격 직후), 키메라 사격이 준비되기 직전에 덫(냉기의 덫은 실탄 장전을 발동시킬 때만), 폭발 사격, 고정 사격, 일제 사격, 신비한 사격. 적이 너무 가까우면 근접 기술, 이동 중에는 즉시 시전 기술, 적이 셋 이상이면 덫, 일제 사격, 연발 사격을 사용합니다. 알림: 매의 상, 마나 10% 미만에서 독사의 상, 사자의 심장, 정조준 오라, 소환수 관리(고독한 늑대를 새겼다면 없음), 광기 5중첩에서 화력 집중, 속사, 정예와 인스턴스에서 종족 특성과 야수의 격노. 실탄 장전을 새겼다면 전투 시작 전 냉기의 덫. 근접 공격 섞기와 위치 선정은 직접 판단합니다."
L["rm.tbc.hunter.ranged.simulator.Name"] = "원거리 공격 전담 (시뮬레이터)"
L["rm.tbc.hunter.ranged.simulator.Description"] = "1–70레벨, 모든 전문화용입니다. 사냥꾼의 징표, 조준 사격, 자동 사격으로 끌어오고, 자동 사격을 계속 유지하며, 대상이 다가오면 근접 공격을 사용합니다. 고정 사격을 배우기 전에는 독사 쐐기를 유지하고, 마나가 넉넉할 때만 조준 사격, 일제 사격, 신비한 사격에 마나를 씁니다. 62레벨부터: 준비되면 일제 사격, 자동 사격 직후마다 고정 사격, 빈틈은 신비한 사격으로 채우고, 혼자일 때는 독사 쐐기를 사용합니다. 셋 이상의 적과 싸우면 일제 사격이 준비될 때마다 사용합니다. 상(마나가 부족하면 독사의 상, 마나가 절반이 되면 다시 매의 상), 소환수 관리, 살상 명령, 정예와 우두머리 상대 주요 재사용 대기시간, 침묵의 사격을 알려 줍니다. 소환수 명령, 눈속임, 덫, 연발 사격, 근접 공격 섞기, 죽은척하기는 직접 판단합니다."
L["rm.tbc.hunter.ranged.wowhead.Name"] = "원거리 공격 전담 (Wowhead)"
L["rm.tbc.hunter.ranged.wowhead.Description"] = "1–70레벨, 모든 전문화용이며 Wowhead의 공격대 조언을 따릅니다. 끌어오기, 근접 공격, 레벨업 사격, 다수 대상 일제 사격, 알림은 시뮬레이터 버전과 같지만, 고정 사격을 배운 뒤에는 자동 사격 후마다 일제 사격과 고정 사격만 제안합니다: 신비한 사격으로 빈틈 채우기 없음(이동 중 제외), 독사 쐐기 없음, 독사의 상 알림 없음. 소환수 명령, 눈속임, 덫, 연발 사격, 근접 공격 섞기, 죽은척하기는 직접 판단합니다. 추천 시뮬레이터 원거리 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요."
